@using sv_5c26992535d64bc4811a797383f3bf0a.Models

<nav aria-label="Application steps" class="mb-4">
    <ol class="list-unstyled d-flex justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "pending";
            <li class="step-item @status text-center flex-fill"
                role="button"
                @onclick="() => GoToStep(step)"
                style="cursor: @(step < CurrentStep ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle @(status == "completed" ? "bg-success text-white" : status == "active" ? "bg-primary text-white" : "bg-secondary text-white")"
                     style="width:36px;height:36px;font-size:0.85rem;">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@(status == "pending" ? "text-muted" : "")">@StepNames[step]</small>
            </li>
            @if (step < StepNames.Length - 1)
            {
                <li class="flex-fill d-flex align-items-center px-0" style="max-width:60px;">
                    <hr class="w-100 @(step < CurrentStep ? "border-success" : "")" />
                </li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
            await OnStepClicked.InvokeAsync(step);
    }
}

@using sv_5c26992535d64bc4811a797383f3bf0a.Models

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control" @bind="Model.FullName" />
</div>
<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control" @bind="Model.Email" />
</div>
<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control" @bind="Model.Phone" />
</div>
<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control" rows="2" @bind="Model.Address"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var valid = await ValidateEmail(Model.Email);
            if (!valid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@using sv_5c26992535d64bc4811a797383f3bf0a.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
