@using sv_5c26992535d64bc4811a797383f3bf0a.Models

<nav aria-label="Application steps" class="mb-4">
    <ol class="list-unstyled d-flex justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "pending";
            <li class="step-item @status text-center flex-fill"
                role="button"
                @onclick="() => GoToStep(step)"
                style="cursor: @(step < CurrentStep ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle @(status == "completed" ? "bg-success text-white" : status == "active" ? "bg-primary text-white" : "bg-secondary text-white")"
                     style="width:36px;height:36px;font-size:0.85rem;">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@(status == "pending" ? "text-muted" : "")">@StepNames[step]</small>
            </li>
            @if (step < StepNames.Length - 1)
            {
                <li class="flex-fill d-flex align-items-center px-0" style="max-width:60px;">
                    <hr class="w-100 @(step < CurrentStep ? "border-success" : "")" />
                </li>
            }
        }
    </ol>
</nav>

@code {
